import { NextResponse } from "next/server";
import { z } from "zod";
import { getDb } from "@taklifnoma/database";
import { apiError, ApiError, readJson } from "@/server/api";
import {
  publicInvitation,
  resolveGuest,
  submissionLimit,
} from "@/server/public";
import { verifySameOrigin } from "@/server/auth";
import { digest, randomToken } from "@/server/auth/crypto";
type Context = { params: Promise<{ id: string }> };
export const runtime = "nodejs";
export async function POST(request: Request, { params }: Context) {
  try {
    verifySameOrigin(request);
    const { id } = await params;
    const { invitation, id: invitationId } = await publicInvitation(id);
    const today = new Intl.DateTimeFormat("en-CA", {
      timeZone: invitation.timezone,
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
    }).format(new Date());
    if (
      !invitation.rsvp.enabled ||
      (invitation.rsvp.deadline && invitation.rsvp.deadline < today)
    )
      throw new ApiError(403, "RSVP_CLOSED", "Javob yuborish muddati tugagan.");
    const input = z
      .object({
        name: z.string().trim().min(1).max(100),
        status: z.enum(["yes", "no", "maybe"]),
        partySize: z.number().int().min(0).max(100),
        note: z.string().trim().max(1000).optional().default(""),
        guestToken: z.string().max(128).optional(),
      })
      .parse(await readJson(request, 5000));
    await submissionLimit(request, invitationId, "rsvp");
    const guest = await resolveGuest(invitationId, input.guestToken);
    const cookieName = "taklifnoma_rsvp";
    const previousToken = request.headers
      .get("cookie")
      ?.split(";")
      .map((value) => value.trim())
      .find((value) => value.startsWith(cookieName + "="))
      ?.slice(cookieName.length + 1);
    const responseToken =
      previousToken && /^[a-zA-Z0-9_-]{43}$/.test(previousToken)
        ? previousToken
        : randomToken();
    const responseHash = digest(
      `${invitationId}:${guest ? `guest:${guest.id}` : responseToken}`,
    );
    const party = input.status === "yes" ? input.partySize : 0;
    const maximum = Math.min(
      invitation.rsvp.maxPartySize,
      Number(guest?.max_party_size ?? 100),
    );
    if (input.status === "yes" && (party < 1 || party > maximum))
      throw new ApiError(400, "PARTY_SIZE", "Mehmonlar sonini tekshiring.");
    await getDb().begin(async (tx) => {
      if (guest) {
        await tx`SELECT id FROM invitation_guests WHERE id=${guest.id} FOR UPDATE`;
        await tx`DELETE FROM rsvp_responses WHERE invitation_id=${invitationId} AND guest_id=${guest.id}`;
      }
      await tx`INSERT INTO rsvp_responses(invitation_id,guest_id,name,status,party_size,note,response_token_hash) VALUES(${invitationId},${guest?.id ?? null},${input.name},${input.status},${party},${input.note},${responseHash}) ON CONFLICT(response_token_hash) DO UPDATE SET name=EXCLUDED.name,status=EXCLUDED.status,party_size=EXCLUDED.party_size,note=EXCLUDED.note,created_at=now()`;
    });
    const response = NextResponse.json(
      { ok: true, message: "Javobingiz saqlandi. Rahmat!" },
      { status: 201 },
    );
    response.cookies.set(cookieName, responseToken, {
      httpOnly: true,
      sameSite: "lax",
      secure: new URL(request.url).protocol === "https:",
      path: "/api/public/invitations",
      maxAge: 365 * 24 * 60 * 60,
    });
    return response;
  } catch (e) {
    return apiError(e);
  }
}
